//! Page structs for requests. Display values are computed here from loaded rows; no
//! database access (.offrails/structure.md). Generated by `cargo offrails generate resource requests agent:references{agent} title:string description:text category:string location:string budget:money`.

use askama::Template;

use super::Ctx;
use crate::models::{Errors, request};
use crate::routes::paths;

/// One request as pages show it: every value a display string.
/// APP: times are shown in UTC; convert to the reader's zone here when the app knows it.
#[derive(Debug, Clone)]
pub struct RequestView {
    pub id: i64,
    pub label: String,
    pub agent_id: String,
    pub title: String,
    pub description: String,
    pub category: String,
    pub location: String,
    pub budget_cents: String,
}

impl RequestView {
    pub fn from_model(r: &request::Model) -> Self {
        Self {
            id: r.id,
            label: r.label(),
            agent_id: format!("Agent #{}", r.agent_id),
            title: r.title.clone(),
            description: r.description.clone(),
            category: r.category.clone(),
            location: r.location.clone(),
            budget_cents: request::money_to_string(r.budget_cents),
        }
    }
}

/// `GET /requests`
#[derive(Template)]
#[template(path = "requests/index.html")]
pub struct RequestsIndex {
    pub ctx: Ctx,
    pub requests: Vec<RequestView>,
    pub page: u64,
    pub more: bool,
}

impl RequestsIndex {
    /// The pagination component's page count: this one, and the next when the query found more
    /// (no COUNT query).
    pub fn pages(&self) -> u64 {
        self.page + u64::from(self.more)
    }

    /// Where its links go (`{base}page=n`).
    pub fn page_base(&self) -> String {
        format!("{}?", paths::requests())
    }
}

/// `GET /requests/{id}`
#[derive(Template)]
#[template(path = "requests/show.html")]
pub struct RequestsShow {
    pub ctx: Ctx,
    pub request: RequestView,
}

/// `GET /requests/new`, and a failed create (422).
#[derive(Template)]
#[template(path = "requests/new.html")]
pub struct RequestsNew {
    pub ctx: Ctx,
    pub params: request::RequestParams,
    pub errors: Errors,
    pub action: String,
    pub choices: RequestChoices,
}

/// `GET /requests/{id}/edit`, and a failed update (422).
#[derive(Template)]
#[template(path = "requests/edit.html")]
pub struct RequestsEdit {
    pub ctx: Ctx,
    pub id: i64,
    pub params: request::RequestParams,
    pub errors: Errors,
    pub action: String,
    pub choices: RequestChoices,
}

/// The form's `<select>` options: (id, label).
#[derive(Debug, Clone, Default)]
pub struct RequestChoices {
    pub agent: Vec<(i64, String)>,
}
